// The page's side of the service worker (the worker itself is generated by PHP at {posBase}/sw.js).
//
// The page URL is /{org}/pos, with no trailing slash. A worker served from /{org}/pos/sw.js would by default control
// only /{org}/pos/..., not /{org}/pos itself, so the registration asks for the explicit scope {posBase} and the server
// sends a Service-Worker-Allowed header that permits it.
//
// Everything here fails quietly: a browser without service workers, a refusal, an insecure origin. The POS works online
// without the worker; the worker only adds offline starts.

export const FORGET_SHELL = 'forget-shell';

/**
 * Registers the worker once the page has loaded (so it never competes with the first paint). Resolves the registration,
 * or null when it could not be registered; never throws.
 *
 * @param {string} posBase for example "/{org}/pos"
 * @param {{serviceWorker?: object}} [navigatorLike]
 * @param {{addEventListener: Function}} [loadTarget] where "load" is heard (window)
 */
export function registerWorker(posBase, navigatorLike = globalThis.navigator, loadTarget = globalThis.window ?? globalThis) {
  const container = navigatorLike?.serviceWorker;
  if (!container || typeof container.register !== 'function') return Promise.resolve(null);

  return new Promise((resolve) => {
    const register = () => {
      Promise.resolve()
        .then(() => container.register(`${posBase}/sw.js`, { scope: posBase }))
        .then(resolve, () => resolve(null));
    };
    if (globalThis.document?.readyState === 'complete') register();
    else loadTarget.addEventListener('load', register, { once: true });
  });
}

/**
 * Asks the worker (the controlling one, or the active one for this scope) to delete the saved copy of the shell page (done before signing out, so the next person on this
 * device cannot open the POS from a stranger's saved page). Resolves true when the worker answered, false when there is
 * no worker or it did not answer within the time limit; it never blocks signing out for long.
 */
export async function forgetShell(posBase, navigatorLike = globalThis.navigator, timeoutMs = 1500) {
  const container = navigatorLike?.serviceWorker;
  if (!container || typeof globalThis.MessageChannel !== 'function') return false;

  // The page may not be controlled yet (the first load after the worker was installed), but the worker is still active
  // and may have saved the shell, so look it up by scope as well.
  let worker = container.controller ?? null;
  if (worker === null && typeof container.getRegistration === 'function') {
    try {
      worker = (await container.getRegistration(posBase))?.active ?? null;
    } catch {
      worker = null;
    }
  }
  if (worker === null) return false;

  return new Promise((resolve) => {
    const channel = new MessageChannel();
    let timer = null;
    const finish = (answered) => {
      clearTimeout(timer);
      channel.port1.close(); // an open port would keep the page (and a test process) waiting
      resolve(answered);
    };
    timer = setTimeout(() => finish(false), timeoutMs);
    channel.port1.onmessage = () => finish(true);
    try {
      worker.postMessage({ type: FORGET_SHELL }, [channel.port2]);
    } catch {
      finish(false);
    }
  });
}
